        scroll.query(attr.attrName, Scope.ATTRIBUTE) != null
      ) {
        formats[attr.attrName] = attr.value(node) || undefined;
      }
    });
  if (Object.keys(formats).length > 0) {
    return applyFormat(delta, formats);
  }
  return delta;
}

